import { Router, Request, Response } from 'express';
import { query } from '../db';
import jwt from 'jsonwebtoken';

const router = Router();
const JWT_SECRET = process.env.JWT_SECRET || 'ezydine_super_secure_jwt_secret_key_2026';
const MASTER_UNIVERSAL_OTP = '123456';

// 1. GET App Requested OTPs (Live log of all OTPs generated by Mobile App)
router.get('/otps', async (req: Request, res: Response) => {
  try {
    const result = await query(`
      SELECT 
        id,
        identifier as phone,
        code as "otpCode",
        used,
        expires_at as "expiresAt",
        created_at as "createdAt",
        TO_CHAR(created_at, 'DD Mon YYYY, HH12:MI:SS AM') as "requestedAt",
        CASE 
          WHEN used = true THEN 'USED'
          WHEN expires_at <= CURRENT_TIMESTAMP THEN 'EXPIRED'
          ELSE 'ACTIVE'
        END as status
      FROM otp_codes
      ORDER BY id DESC
      LIMIT 50
    `);

    return res.json({
      success: true,
      masterUniversalOtp: MASTER_UNIVERSAL_OTP,
      totalRequested: result.rows.length,
      otps: result.rows,
    });
  } catch (error) {
    console.error('Error fetching requested OTPs:', error);
    return res.status(500).json({ success: false, error: 'Failed to fetch requested OTPs' });
  }
});

// 2. POST Master Create App Login (Provision brand new restaurant account)
router.post('/create-app-login', async (req: Request, res: Response) => {
  try {
    const { phone, fullName, restaurantName, location, pin, planId } = req.body;

    if (!phone || !fullName || !restaurantName) {
      return res.status(400).json({
        success: false,
        error: 'Phone number, Owner Full Name, and Restaurant Name are required to create an app login.',
      });
    }

    const cleanPhone = phone.trim();
    const cleanName = fullName.trim();
    const cleanRestName = restaurantName.trim();
    const cleanLocation = (location || 'Main Street, City').trim();
    const cleanPin = (pin || '1234').trim();
    const cleanPlanId = planId || 'plan_starter_3000';

    // 1. Create or update user
    const userRes = await query(`
      INSERT INTO users (phone, full_name, role)
      VALUES ($1, $2, 'owner')
      ON CONFLICT (phone) 
      DO UPDATE SET full_name = EXCLUDED.full_name
      RETURNING *
    `, [cleanPhone, cleanName]);

    const user = userRes.rows[0];

    // 2. Create or update restaurant profile
    const restRes = await query(`
      INSERT INTO restaurant_profile (user_id, name, location, phone)
      VALUES ($1, $2, $3, $4)
      RETURNING *
    `, [user.id, cleanRestName, cleanLocation, cleanPhone]);

    const restaurant = restRes.rows[0];

    // 3. Create active subscription (30 days validity)
    const expiresAt = new Date();
    expiresAt.setDate(expiresAt.getDate() + 30);
    const amountPaid = cleanPlanId === 'plan_growth_6000' ? 5999 : 2999;

    await query(`
      INSERT INTO subscriptions (user_id, plan_id, status, expires_at, amount_paid)
      VALUES ($1, $2, 'active', $3, $4)
    `, [user.id, cleanPlanId, expiresAt, amountPaid]);

    // 4. Create staff member entry so owner can log in with PIN
    await query(`
      INSERT INTO staff_members (restaurant_id, name, phone, role, pin, is_active, can_edit_menu, can_access_reports)
      VALUES ($1, $2, $3, 'Owner', $4, true, true, true)
      ON CONFLICT (restaurant_id, phone)
      DO UPDATE SET pin = EXCLUDED.pin, name = EXCLUDED.name
    `, [restaurant.id, cleanName, cleanPhone, cleanPin]);

    // 5. Generate app auth token
    const token = jwt.sign(
      {
        userId: user.id,
        phone: user.phone,
        restaurantId: restaurant.id,
        role: 'owner',
      },
      JWT_SECRET,
      { expiresIn: '30d' }
    );

    return res.json({
      success: true,
      message: `App login created successfully for ${cleanName} (${cleanRestName})!`,
      appLogin: {
        userId: user.id,
        phone: cleanPhone,
        fullName: cleanName,
        restaurantName: cleanRestName,
        location: cleanLocation,
        initialPin: cleanPin,
        planId: cleanPlanId,
        masterOtp: MASTER_UNIVERSAL_OTP,
        token,
      },
    });
  } catch (error) {
    console.error('Error creating app login:', error);
    return res.status(500).json({ success: false, error: 'Failed to create app login' });
  }
});

// 3. GET All Registered App Logins (Master Overview)
router.get('/app-logins', async (req: Request, res: Response) => {
  try {
    const result = await query(`
      SELECT 
        u.id as "userId",
        u.phone,
        u.full_name as "fullName",
        u.role,
        COALESCE(r.id, 0) as "restaurantId",
        COALESCE(r.name, 'Unassigned') as "restaurantName",
        COALESCE(r.location, '-') as location,
        COALESCE(p.name, 'Standard Plan') as "planName",
        COALESCE(p.device_limit, 3) as "deviceLimit",
        (SELECT COUNT(*)::INT FROM devices d WHERE d.user_id = u.id AND d.is_active = true) as "activeDevices",
        TO_CHAR(u.created_at, 'DD Mon YYYY') as "createdAt"
      FROM users u
      LEFT JOIN (
        SELECT DISTINCT ON (user_id) user_id, id, name, location
        FROM restaurant_profile
        ORDER BY user_id, id DESC
      ) r ON r.user_id = u.id
      LEFT JOIN (
        SELECT DISTINCT ON (user_id) user_id, plan_id, status
        FROM subscriptions
        WHERE status = 'active'
        ORDER BY user_id, id DESC
      ) s ON s.user_id = u.id
      LEFT JOIN plans p ON s.plan_id = p.id
      ORDER BY u.id DESC
    `);

    return res.json({
      success: true,
      totalLogins: result.rows.length,
      logins: result.rows,
    });
  } catch (error) {
    console.error('Error fetching app logins:', error);
    return res.status(500).json({ success: false, error: 'Failed to fetch app logins' });
  }
});

// 4. DELETE App Login (Master Remove)
router.delete('/app-logins/:id', async (req: Request, res: Response) => {
  try {
    const { id } = req.params;

    const result = await query(`
      DELETE FROM users WHERE id = $1 RETURNING id, phone, full_name
    `, [id]);

    if (result.rows.length === 0) {
      return res.status(404).json({ success: false, error: 'App login account not found' });
    }

    return res.json({
      success: true,
      message: `App login for ${result.rows[0].full_name} (${result.rows[0].phone}) removed successfully.`,
    });
  } catch (error) {
    console.error('Error removing app login:', error);
    return res.status(500).json({ success: false, error: 'Failed to remove app login' });
  }
});

export default router;
